/**
 * Regenerate `src/widget-logos.ts` from `images/`.
 *
 *   node scripts/build-widget-logos.mjs [size]
 *
 * A widget must stay under 4096 bytes after zlib level 9, and a data: image
 * barely compresses, so every byte here is bought from the widget's own CSS.
 * PNG-8 with a 16-colour palette beats WebP ~3x on these flat logos; sizing
 * the asset to its on-screen pixel size (no scaling in the client) keeps the
 * palette small.
 *
 * `sharp` comes in through wrangler, so this is a one-off maintenance script,
 * not part of `pnpm run deploy`: the generated file is committed.
 */
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const sharp = require("sharp");

const SIZE = Number(process.argv[2] ?? 30);
const OUT = path.join(process.cwd(), "src", "widget-logos.ts");

// Fewer palette entries = fewer bytes. Telebirr and M-Pesa are flat enough for
// 4 colours at this size; CBE Birr keeps its yellow accent at 8.
const sources = [
  ["TELEBIRR", "images/telebirr-logo.png", 4],
  ["MPESA", "images/M-PESA-logo.png", 4],
  ["CBE", "images/cbe-birr-logo.png", 8],
];

const lines = [
  "/** Generated by `node scripts/build-widget-logos.mjs`. Do not edit by hand. */",
  "",
];

let bytes = 0;
for (const [name, file, colours] of sources) {
  const buffer = await sharp(fs.readFileSync(file))
    .trim()
    .resize(SIZE, SIZE, {
      fit: "contain",
      background: { r: 0, g: 0, b: 0, alpha: 0 },
    })
    .png({ palette: true, colours, effort: 10, compressionLevel: 9 })
    .toBuffer();
  bytes += buffer.length;
  lines.push(
    `export const LOGO_${name} =`,
    `  "data:image/png;base64,${buffer.toString("base64")}";`,
    "",
  );
  console.log(`${name.padEnd(9)} ${SIZE}px ${colours}c  ${buffer.length} B`);
}

fs.writeFileSync(OUT, lines.join("\n"));
const base64 = lines.join("").match(/base64,[^"]+/g)?.reduce((n, s) => n + s.length, 0) ?? 0;
console.log(`total ${bytes} B binary, ${base64} B base64 -> ${OUT}`);
